// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

contract Pool {
    mapping(address => uint256) public shares;
    mapping(address => uint256) public credited;

    function deposit() external payable {
        shares[msg.sender] += msg.value;
        credited[msg.sender] += msg.value;
    }

    // Correct on its own: state is zeroed BEFORE the external call.
    function withdraw() external {
        uint256 amount = shares[msg.sender];
        shares[msg.sender] = 0;
        (bool ok, ) = msg.sender.call{value: amount}("");
        require(ok, "transfer failed");
    }

    // Also correct on its own — and it pays from a ledger withdraw() never cleared.
    function refund() external {
        uint256 amount = credited[msg.sender];
        require(amount > 0, "nothing to refund");
        credited[msg.sender] = 0;
        (bool ok, ) = msg.sender.call{value: amount}("");
        require(ok, "refund failed");
    }
}
